\end{proof}

\begin{proof}
Let $R$ be a subring of a field $F$ containing $1_F$. The ring $R$ is commutative because its multiplication is inherited from the commutative multiplication of $F$, and it has identity $1_F$. If $a,b\in R$ satisfy $ab=0$, then the equality holds in $F$. Since $F$ is a field, either $a=0$ or $b=0$. Hence $R$ has no zero divisors. Consequently, $R$ is a commutative ring with identity and no zero divisors, so it is an integral domain.
\end{proof}

\begin{proof}
